#include <iostream>
#include <string>
#include <vector>

int main() {
    std::string user_input;
    std::getline(std::cin, user_input);
    std::vector<char> chars_list;
    bool found_at_symbol = true;
    for (size_t idx = 0; idx < user_input.length(); ++idx) {
        char c = user_input[idx];
        if (idx >= 2 && idx + 1 < user_input.length() &&
            user_input.substr(idx - 2, 3) == "dot") {
            // Remove last two characters if possible
            if (chars_list.size() >= 2) {
                chars_list.pop_back();
                chars_list.pop_back();
            }
            chars_list.push_back('.');
        } else if (idx >= 1 && idx + 1 < user_input.length() &&
                   user_input.substr(idx - 1, 2) == "at" && found_at_symbol && idx != 1 && idx != user_input.length() - 1) {
            if (!chars_list.empty()) {
                chars_list.pop_back();
            }
            chars_list.push_back('@');
            found_at_symbol = false;
        } else {
            chars_list.push_back(c);
        }
    }
    std::string result_str;
    for (char ch : chars_list) {
        result_str += ch;
    }
    std::cout << result_str << std::endl;
    return 0;
}
